app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, secure: true, maxAge: 15 * 60 * 1000 }
}));

// After login succeeds: store the user in the session
